files.content:
.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #eaeaea;
  --vt-ink: #000000;
  --vt-ink-soft: #565758;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #000000;
  --vt-accent-on-deep: #6ea8ff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink-soft);
  padding-top: 94px;
  line-height: 1.5;
  box-sizing: border-box;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: inherit;
}

.root a {
  color: var(--vt-ink-soft);
  text-decoration: none;
  transition: color 0.3s, background-color 0.3s;
}

.root a:hover {
  color: var(--vt-accent);
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.root h1,
.root h2,
.root h3,
.root h4,
.root h5,
.root h6 {
  color: var(--vt-ink);
  font-weight: 600;
  line-height: 1.2;
  margin: 0 0 0.5rem;
}

.root h1 {
  font-size: 48px;
  font-weight: 700;
}

.root h2 {
  font-size: 36px;
  font-weight: 700;
}

.root h5 {
  font-size: 24px;
}

.root p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  line-height: 1.6;
  margin: 0 0 1rem;
}

/* Navigation */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  padding: 20px 0;
}

.navIn {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: inline-block;
  color: var(--vt-accent);
  font-size: 24px;
  font-weight: 700;
  text-align: center;
  margin: 0;
  line-height: 1.2;
}

.logo .brand {
  display: block;
}

.navLinks {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.navLinks a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  padding: 15px 24px;
  display: inline-block;
}

.navLinks a:hover,
.navLinks a:focus {
  color: var(--vt-ink);
}

/* Hero */
.hero {
  position: relative;
  overflow: hidden;
  height: 580px;
}

.heroTrack {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.heroTrack::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  position: relative;
  margin: 0;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  z-index: 2;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  box-shadow: -0.5rem 0 1rem rgba(0, 0, 0, 0.1);
}

.heroText h1 {
  margin-bottom: 0.5rem;
}

.kicker {
  color: var(--vt-accent);
  font-weight: 600;
  margin-bottom: 0.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
  margin-top: 1rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  position: relative;
  overflow: hidden;
}

.customLink::before {
  content: attr(data-hover);
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--vt-line);
  color: var(--vt-accent-ink);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: top 0.3s cubic-bezier(0.19, 1, 0.56, 1);
}

.customLink:hover::before {
  top: 0;
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 0;
}

/* Sections */
.sectionPadding {
  padding: 7rem 0;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.aboutGrid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

.aboutText {
  max-width: 800px;
}

/* Gallery */
.gallerySection {
  padding: 0;
}

.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 1 1 50%;
  margin: 0;
  padding: 0;
}

.galleryItem img {
  width: 100%;
  display: block;
  height: auto;
}

/* Timeline */
.sectionTitle {
  text-align: center;
  margin-bottom: 3rem;
}

.timeline {
  position: relative;
  padding: 0;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 0;
}

.timelineNode {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 1rem;
  margin-bottom: 2rem;
}

.timelineNode:last-child {
  margin-bottom: 0;
}

.timelineContent {
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  border-radius: 0 0 0.25rem 0.25rem;
  padding: 0;
  position: relative;
  grid-column: 1;
}

.timelineContent h3 {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
  color: var(--vt-ink-soft);
}

.timelineIconWrap {
  grid-column: 2;
  position: relative;
  z-index: 1;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

.timelineIcon {
  display: block;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--vt-accent);
}

.timelineDate {
  grid-column: 3;
  padding: 1rem 0;
  font-weight: 600;
  color: var(--vt-ink);
  text-align: right;
}

/* Alternating layout */
.timelineNode.odd .timelineContent {
  grid-column: 1;
}

.timelineNode.odd .timelineDate {
  grid-column: 3;
}

.timelineNode.odd .timelineContent h3,
.timelineNode.odd .timelineContent p {
  text-align: left;
}

.timelineNode.odd .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 100%;
  transform: translateY(-50%);
  width: 0;
  border-left: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNode.even {
  grid-template-columns: 1fr auto 1fr;
}

.timelineNode.even .timelineContent {
  grid-column: 3;
  order: 3;
}

.timelineNode.even .timelineIconWrap {
  grid-column: 2;
  order: 2;
}

.timelineNode.even .timelineDate {
  grid-column: 1;
  order: 1;
  text-align: left;
}

.timelineNode.even .timelineContent h3,
.timelineNode.even .timelineContent p {
  text-align: right;
}

.timelineNode.even .timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  right: 100%;
  transform: translateY(-50%);
  width: 0;
  border-right: 10px solid var(--vt-ink);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

/* Footer */
.siteFooter {
  background: var(--vt-surface-2);
  padding: 7rem 0;
}

.footerGrid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 2rem;
}

.footerCol h5 {
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.footerCol p,
.footerCol ul {
  color: var(--vt-ink-soft);
  font-size: 16px;
}

.copyright {
  margin-top: 3rem;
  text-align: center;
  color: var(--vt-ink-soft);
  font-size: 16px;
}

/* Responsive */
@media screen and (min-width: 1600px) {
  .hero {
    height: 740px;
  }
}

@media screen and (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .root h1 {
    font-size: 38px;
  }

  .root h2 {
    font-size: 32px;
  }

  .root h5 {
    font-size: 20px;
  }

  .sectionPadding {
    padding: 5rem 0;
  }

  .nav {
    padding: 10px 0;
  }

  .navLinks a {
    padding: 5px 10px;
  }

  .hero {
    height: auto;
  }

  .heroTrack {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: auto;
    right: auto;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
    box-shadow: none;
  }

  .footerGrid {
    grid-template-columns: 1fr;
  }
}

@media screen and (max-width: 767px) {
  .timeline::before {
    top: 60px;
    left: 33px;
    transform: none;
    height: 90%;
  }

  .timelineNode {
    display: block;
    position: relative;
    margin-left: 40px;
  }

  .timelineContent,
  .timelineDate,
  .timelineIconWrap {
    grid-column: auto;
    order: initial;
  }

  .timelineIconWrap {
    position: absolute;
    left: -40px;
    top: 0;
    width: 70px;
    height: 70px;
  }

  .timelineIcon {
    width: 16px;
    height: 16px;
  }

  .timelineContent h3,
  .timelineContent p {
    text-align: left !important;
  }

  .timelineContent h3::after {
    left: auto;
    right: 100%;
    border-left: 0;
    border-right: 10px solid var(--vt-ink);
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }

  .timelineNode.even .timelineContent h3::after {
    right: 100%;
    left: auto;
    border-left: 0;
    border-right: 10px solid var(--vt-ink);
  }

  .timelineDate {
    text-align: left !important;
    padding: 0.5rem 0;
  }
}

@media screen and (max-width: 575px) {
  .timeline::before {
    left: 57px;
  }

  .timelineNode {
    margin-left: 50px;
  }

  .timelineIconWrap {
    left: -50px;
  }
}

@media screen and (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks {
    flex-direction: column;
    align-items: flex-start;
  }

  .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
    margin-right: 0;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media screen and (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }
}
